create function pg_temp.oa(n integer) returns void language sql as $$select set_config('request.jwt.claim.sub','d1000000-0000-0000-0000-'||lpad(n::text,12,'0'),true)::text is not null$$;
create function pg_temp.oc(action text,data jsonb default '{}',k text default null,order_key text default 'order') returns uuid language plpgsql as $$declare oid uuid;begin select id into oid from order_ids where key=order_key;return public.order_command(oid,action,data||jsonb_build_object('expected_revision',(public.read_order(oid)->>'revision')::integer,'reason','Synthetic order test'),coalesce(k,gen_random_uuid()::text));end$$;
create function pg_temp.dc(action text,data jsonb default '{}',order_key text default 'order') returns uuid language plpgsql as $$declare oid uuid;begin select id into oid from order_ids where key=order_key;return public.dispatch_command(oid,action,data||jsonb_build_object('expected_revision',(public.read_order(oid)->>'revision')::integer,'reason','Synthetic dispatch test'),gen_random_uuid()::text);end$$;
create function pg_temp.new_quote(k text,corporate boolean default false) returns uuid language plpgsql as $$declare req uuid;q uuid;begin
 perform set_config('request.jwt.claim.sub',case when corporate then 'a1000000-0000-0000-0000-000000000005' else 'a1000000-0000-0000-0000-000000000001' end,true);
 req=public.create_service_request(case when corporate then 'a8000000-0000-0000-0000-000000000001'::uuid else 'a2000000-0000-0000-0000-000000000001'::uuid end,(select id from order_ids where key='service'),case when corporate then 'e3000000-0000-0000-0000-000000000002'::uuid else 'e3000000-0000-0000-0000-000000000001'::uuid end,'{"details":[{"note":"Synthetic job"}]}','synthetic-order-request-'||k,case when corporate then 'aa000000-0000-0000-0000-000000000001'::uuid end);
 perform public.change_service_request(req,1,'submit');perform pg_temp.oa(3);perform public.review_service_request(req,2);
 q=public.prepare_quotation(req,(select id from public.currencies where code='NGN'),now()+interval '1 day','Synthetic order commercial scope','[{"description":"Synthetic work","kind":"labour","quantity":"1","unit_price":"100"}]','synthetic-order-quote-'||k);
 perform pg_temp.oa(4);perform public.decide_quotation(q,'approve');perform set_config('request.jwt.claim.sub',case when corporate then 'a1000000-0000-0000-0000-000000000005' else 'a1000000-0000-0000-0000-000000000001' end,true);perform public.decide_quotation(q,'accept');return q;end$$;
