select pg_temp.assert_true(pg_temp.expect_error($q$select public.read_order((select id from order_ids where key='corporate'))$q$,'42501'),'Revoked branch grant immediately removes order access');
-- Leave only isolated, explicit no-upfront-payment orders for multi-connection races.
select pg_temp.oa(4);select public.order_policy_command('retire',jsonb_build_object('id',(select id from order_ids where key='credit_policy')),'synthetic-credit-retire');
select pg_temp.oa(3);insert into order_ids values('race_policy',public.order_policy_command('prepare',jsonb_build_object('service_version_id',(select id from order_ids where key='service'),'version',3,'valid_from',now()-interval '1 day','payment_gate','no_upfront_payment','offer_seconds',3600,'performance_weight','2','workload_weight','1'),'synthetic-race-policy'));
select pg_temp.oa(4);select public.order_policy_command('approve',jsonb_build_object('id',(select id from order_ids where key='race_policy')),'synthetic-race-policy-approve');
insert into order_ids values('race_quote1',pg_temp.new_quote('race-one')),('race_quote2',pg_temp.new_quote('race-two')),('race_quote3',pg_temp.new_quote('race-three'));
insert into order_ids values('multi_quote',pg_temp.new_quote('multi-provider'));
insert into order_ids values('multi_order',public.create_service_order((select id from order_ids where key='multi_quote'),jsonb_build_object('zone_id',(select id from order_ids where key='zone'),'start',now()+interval '1 day','end',now()+interval '1 day 1 hour','reason','Synthetic multi-provider order'),'synthetic-multi-order'));
select pg_temp.oa(4);select pg_temp.oc('release','{}',null,'multi_order');
select pg_temp.assert_true(jsonb_array_length(public.discover_order_candidates((select id from order_ids where key='multi_order'),'kg','5'))>=4,'Bounded discovery identifies qualified personnel across contracting businesses');
select pg_temp.assert_true(public.read_order_policy((select id from order_ids where key='race_policy'))->>'payment_gate'='no_upfront_payment','Operational payment gate comes from independently approved configuration');
insert into order_payload select 'multi',jsonb_agg(value->'id') from jsonb_array_elements(public.match_order((select id from order_ids where key='multi_order'),'[{"provider_id":"d3000000-0000-0000-0000-000000000001","worker_id":"d1000000-0000-0000-0000-000000000001","units":"5"},{"provider_id":"d3000000-0000-0000-0000-000000000002","worker_id":"d1000000-0000-0000-0000-000000000002","units":"5"}]'));
select pg_temp.oa(3);insert into order_ids values('multi_proposal',pg_temp.dc('propose',jsonb_build_object('candidates',(select payload from order_payload where key='multi')),'multi_order'));
reset role;insert into order_ids select 'multi_offer1',id from private.assignment_offers where proposal_id=(select id from order_ids where key='multi_proposal') and provider_id='d3000000-0000-0000-0000-000000000001';
insert into order_ids select 'multi_offer2',id from private.assignment_offers where proposal_id=(select id from order_ids where key='multi_proposal') and provider_id='d3000000-0000-0000-0000-000000000002';
set local role authenticated;select set_config('request.jwt.claim.sub','e1000000-0000-0000-0000-000000000001',true);select pg_temp.dc('respond',jsonb_build_object('offer_id',(select id from order_ids where key='multi_offer1'),'accept',true),'multi_order');
select pg_temp.assert_true(jsonb_array_length(public.read_order((select id from order_ids where key='multi_order'))->'offers')=1,'Contracting business cannot inspect the other business offer or personnel');
select pg_temp.oa(3);
select pg_temp.assert_true(pg_temp.expect_error($q$select pg_temp.dc('confirm',jsonb_build_object('id',(select id from order_ids where key='multi_proposal')),'multi_order')$q$,'23514'),'One provider response cannot confirm a multi-provider bundle');
select set_config('request.jwt.claim.sub','e1000000-0000-0000-0000-000000000002',true);select pg_temp.dc('respond',jsonb_build_object('offer_id',(select id from order_ids where key='multi_offer2'),'accept',true),'multi_order');
select pg_temp.oa(3);select pg_temp.dc('confirm',jsonb_build_object('id',(select id from order_ids where key='multi_proposal')),'multi_order');
select pg_temp.assert_true(public.read_order((select id from order_ids where key='multi_order'))->>'internal_status'='assigned','Two separately accepting contracting businesses share one atomic assignment bundle');
select pg_temp.dc('reassign','{}','multi_order');
select set_config('request.jwt.claim.sub','a1000000-0000-0000-0000-000000000001',true);
insert into order_ids values('amend_quote',pg_temp.new_quote('amendment'));
insert into order_ids values('commercial_change',pg_temp.oc('propose_change',jsonb_build_object('kind','amend','proposal',jsonb_build_object('quotation_version_id',(select id from order_ids where key='amend_quote')))));
select pg_temp.oa(4);select pg_temp.oc('decide_change',jsonb_build_object('id',(select id from order_ids where key='commercial_change'),'approve',true));
select pg_temp.assert_true(public.read_order((select id from order_ids where key='order'))->'commercial'->>'id'=(select id::text from order_ids where key='amend_quote'),'Approved amendment pins a newly accepted commercial version');
select pg_temp.oc('release');
select set_config('request.jwt.claim.sub','a1000000-0000-0000-0000-000000000001',true);
insert into order_ids values('cancel_change',pg_temp.oc('propose_change','{"kind":"cancel"}'));
select pg_temp.oa(4);select pg_temp.oc('decide_change',jsonb_build_object('id',(select id from order_ids where key='cancel_change'),'approve',true));
select pg_temp.assert_true(public.read_order((select id from order_ids where key='order'))->>'status'='cancelled','Customer-proposed cancellation takes the controlled independent decision path');
select pg_temp.assert_true(pg_temp.expect_error($q$select pg_temp.oc('resume')$q$,'40001'),'Cancelled orders cannot be revived through a status shortcut');
reset role;
select pg_temp.assert_true((select count(*)=2 from private.order_commercial_versions where order_id=(select id from order_ids where key='order')),'Commercial amendment preserves both immutable quotation links');
select pg_temp.assert_true((select count(*)>1 from private.order_history where order_id=(select id from order_ids where key='order') and order_snapshot ? 'starts_at'),'Schedule and policy snapshots retained with domain history');
select pg_temp.assert_true(not has_function_privilege('anon','public.order_command(uuid,text,jsonb,text)','EXECUTE') and not has_function_privilege('anon','public.dispatch_command(uuid,text,jsonb,text)','EXECUTE'),'Anonymous order and dispatch execution explicitly denied');
savepoint worker_order_provenance;
update private.operational_event_deliveries d set available_at=now()+interval '1 day' from private.operational_events e where e.id=d.event_id and e.order_id is null;
grant execute on function pg_temp.assert_true(boolean,text) to service_role;
set local role service_role;select set_config('request.jwt.claim.role','service_role',true);
select pg_temp.assert_true((public.operational_event_worker('claim','{"limit":1,"lease_seconds":60,"max_attempts":3}')->0->>'order_id') is not null,'Existing outbox worker carries typed order provenance without provider identity fabrication');
reset role;rollback to worker_order_provenance;
rollback;
